package algorithms.trees;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class BinaryTree {
public static class TreeNode<T>{public T value;public TreeNode<T> left,right;public TreeNode(T value,TreeNode<T> left,TreeNode<T> right){this.value=value;this.left=left;this.right=right;}}public static <T> TreeNode<T> treeNode(T v){return treeNode(v,null,null);}public static <T> TreeNode<T> treeNode(T v,TreeNode<T> l,TreeNode<T> r){return new TreeNode<>(v,l,r);}public static <T> TreeNode<T> fromLevelOrder(List<T> a){if(a.isEmpty()||a.get(0)==null)return null;TreeNode<T> root=treeNode(a.get(0));List<TreeNode<T>> q=new ArrayList<>();q.add(root);int i=1;for(int h=0;h<q.size()&&i<a.size();h++){TreeNode<T> n=q.get(h);T v=a.get(i++);if(v!=null){n.left=treeNode(v);q.add(n.left);}if(i<a.size()){v=a.get(i++);if(v!=null){n.right=treeNode(v);q.add(n.right);}}}return root;}public static <T> List<T> preOrder(TreeNode<T> root){List<T> o=new ArrayList<>();Deque<TreeNode<T>> s=new ArrayDeque<>();if(root!=null)s.push(root);while(!s.isEmpty()){TreeNode<T> n=s.pop();o.add(n.value);if(n.right!=null)s.push(n.right);if(n.left!=null)s.push(n.left);}return o;}public static <T> List<T> inOrder(TreeNode<T> root){List<T> o=new ArrayList<>();Deque<TreeNode<T>> s=new ArrayDeque<>();TreeNode<T> n=root;while(n!=null||!s.isEmpty()){while(n!=null){s.push(n);n=n.left;}n=s.pop();o.add(n.value);n=n.right;}return o;}public static <T> List<T> postOrder(TreeNode<T> root){List<T> o=new ArrayList<>();Deque<TreeNode<T>> s=new ArrayDeque<>();if(root!=null)s.push(root);while(!s.isEmpty()){TreeNode<T> n=s.pop();o.add(n.value);if(n.left!=null)s.push(n.left);if(n.right!=null)s.push(n.right);}Collections.reverse(o);return o;}public static <T> List<List<T>> levelOrder(TreeNode<T> root){List<List<T>> o=new ArrayList<>();List<TreeNode<T>> level=new ArrayList<>();if(root!=null)level.add(root);while(!level.isEmpty()){List<T> vals=new ArrayList<>();List<TreeNode<T>> next=new ArrayList<>();for(TreeNode<T> n:level){vals.add(n.value);if(n.left!=null)next.add(n.left);if(n.right!=null)next.add(n.right);}o.add(vals);level=next;}return o;}public static <T> int maxDepth(TreeNode<T> root){return root==null?0:1+Math.max(maxDepth(root.left),maxDepth(root.right));}public static Double maxValue(TreeNode<Double> root){Double max=null;for(double v:preOrder(root))if(max==null||v>max)max=v;return max;}public static boolean isValidBst(TreeNode<Double> root){return isValidBst(root,Double.NEGATIVE_INFINITY,Double.POSITIVE_INFINITY);}public static boolean isValidBst(TreeNode<Double> root,double low,double high){return root==null||root.value>low&&root.value<high&&isValidBst(root.left,low,root.value)&&isValidBst(root.right,root.value,high);}public static <T> TreeNode<T> invertTree(TreeNode<T> root){if(root==null)return null;TreeNode<T> l=invertTree(root.right),r=invertTree(root.left);root.left=l;root.right=r;return root;}public static TreeNode<Double> lowestCommonAncestorBst(TreeNode<Double> root,double a,double b){while(root!=null){if(a<root.value&&b<root.value)root=root.left;else if(a>root.value&&b>root.value)root=root.right;else return root;}return null;}
}
